package com.mahweb.mahyarnfc.omnishare.nearby;
import com.mahweb.mahyarnfc.omnishare.ble.*; import java.util.*;
public final class NearbyDeviceRegistry { public static final class Entry { public final String tokenHex,alias; public int capabilities,lastRssi; public long lastSeen; public final RssiFilter filter=new RssiFilter(); Entry(String t){tokenHex=t;alias="Mahyar nearby • "+t.substring(Math.max(0,t.length()-4)).toUpperCase(Locale.US);} public ProximityBucket proximity(){return filter.bucket();} }
 private final LinkedHashMap<String,Entry>m=new LinkedHashMap<>(); public synchronized Entry observe(BleObservation o){Entry e=m.get(o.tokenHex);if(e==null){e=new Entry(o.tokenHex);m.put(o.tokenHex,e);}e.lastRssi=o.rssi;e.lastSeen=o.seenAt;e.capabilities=o.capabilities;e.filter.add(o.rssi);return e;} public synchronized List<Entry> snapshot(long now){m.values().removeIf(e->now-e.lastSeen>15000L);return new ArrayList<>(m.values());} public synchronized void clear(){m.clear();} }
